    return float2(
      dot(float3(material.normalMatrix[1][1], material.normalMatrix[2][1], material.normalMatrix[3][1]), mapped),
      dot(float3(material.normalMatrix[0][2], material.normalMatrix[1][2], material.normalMatrix[2][2]), mapped));
